from phonebook_rt import (
    collections_ as _pb_collections,
    core as _pb_core,
    io_ as _pb_io,
    logic_ as _pb_logic,
    numbers_ as _pb_numbers,
    text as _pb_text,
)


def tally_of(entry):
    """000-0000001  TALLY_OF

    A local extension: this is custom logic, not a registered address.
    """
    tally = entry[1]
    return tally


def as_line(entry):
    """000-0000002  AS_LINE

    A local extension: this is custom logic, not a registered address.
    """
    word = entry[0]
    tally = entry[1]
    shown = _pb_core.to_text(tally)
    parts = [word, shown]
    line = ": ".join(parts)
    return line


def main() -> None:
    raw = _pb_io.read_text_file("examples/data/speech.txt")
    lowered = _pb_text.lowercase(raw)
    nodots = _pb_text.replace(lowered, ".", " ")
    clean = _pb_text.replace(nodots, ",", " ")
    words = _pb_text.split_words(clean)
    tallies = _pb_collections.count_occurrences(words)
    entries = [(_pb_k, tallies[_pb_k]) for _pb_k in sorted(tallies)]
    ranked = _pb_collections.sort_by(entries, tally_of, True)
    top = _pb_collections.take(ranked, 10)
    report = [as_line(_pb_x) for _pb_x in top]
    _pb_core.print_lines(report)


